86	/// KatalogTierEngineCallable -- GoF Object Adapter: adaptiert einen realen IObservableTier an die
87	/// cmd::EngineCallable-Signatur. Pro Op wird EINE reale Gattungs-Operation (insert + lookup ueber den
88	/// gemeinsamen uint64-Key-Raum nach Umstufung-B) auf der geladenen Komposition getrieben; ExecuteEngineCommand
89	/// timet jeden Aufruf -> die per-Op-Latenz stammt aus dem ECHTEN Tier (kein Surrogat, keine Simulation).
90	class KatalogTierEngineCallable {
91	public:
92	    explicit KatalogTierEngineCallable(an::IObservableTier& tier) noexcept : tier_{&tier} {}
93	
94	    cmd::OperationOutcome operator()(std::size_t op, cmd::WorkloadKind /*kind*/, std::uint64_t seed) const noexcept {
95	        // Deterministischer Schluessel je Op (gleiche Config + Seed => reproduzierbare Sequenz je Engine).
96	        std::uint64_t const key = (static_cast<std::uint64_t>(op) * 2654435761ull) ^ seed;
97	        (void)tier_->tier_insert(key, key * 7u +
98	                                          1u); // reale Gattungs-Op #1 (T0 search_algo + T3 path_compression gekoppelt)
99	        std::uint64_t         v   = 0;
100	        bool const            hit = tier_->tier_lookup(key, &v); // reale Gattungs-Op #2
101	        cmd::OperationOutcome out{};
102	        out.cache_misses_delta = 0; // ehrlich: ohne PMC in-process nicht messbar (kein Fabrikat)
103	        out.bytes_touched      = sizeof(std::uint64_t) * 2; // key + value ueber die vtable beruehrt
104	        out.success            = hit; // gerade eingefuegter Key MUSS gefunden werden (std::map-Konform)
105	        return out;
106	    }
107	
108	private:
109	    an::IObservableTier* tier_;
110	};
