134	/// execute_one_permutation_katalog -- die W4-Gate-Variante von V32Orchestrator::execute_one_permutation
135	/// (v32_orchestrator.hpp:148-180). EE-A = reale Stufe1_CeOnly-Katalog-Tier (StufeOneC, CE-SOTA-Baseline),
136	/// EE-B = reale Stufe2_PrueflingReplace-Katalog-Tier (StufeTwoC, PRT ersetzt den path_compression-Slot). BEIDE
137	/// ueber den CEB-Pfad (IObservableTier -> Pruefdock -> ExecuteEngineCommand); die per-Op-Latenzen ->
138	/// CompareEngineCommand/Welch (UNVERAENDERT). Die Defaults sind das gepinnte Reihe-A-Paar (HOT-Host);
139	/// der Aufrufer (Stufe G) waehlt per-Host ueber die Template-Parameter.
140	template <class StufeOneC = comp::HotComposition, class StufeTwoC = comp::HotPrtStufe2ReplaceComposition>
141	[[nodiscard]] inline KatalogPermutationOutcome execute_one_permutation_katalog(std::string_view     axis_id,
142	                                                                               std::string_view     variant_name,
143	                                                                               cmd::Workload const& workload) {
144	    KatalogPermutationOutcome outcome;
145	    outcome.axis_id      = std::string(axis_id);
146	    outcome.variant_name = std::string(variant_name);
147	
148	    outcome.ee_a_result = drive_one_engine<StufeOneC>("Stufe1_CeOnly-Katalog-Tier(EE-A)", workload,
149	                                                      outcome.ee_a_conformance_cases, outcome.ee_a_conformance_passed);
150	    outcome.ee_b_result = drive_one_engine<StufeTwoC>("Stufe2_PrueflingReplace-Katalog-Tier(EE-B)", workload,
151	                                                      outcome.ee_b_conformance_cases, outcome.ee_b_conformance_passed);
152	
153	    cmd::CompareEngineCommand compare(outcome.ee_a_result, outcome.ee_b_result);
154	    compare.execute();
155	    outcome.verdict          = compare.verdict();
156	    outcome.throughput_ratio = compare.throughput_ratio();
157	    if (compare.welch().valid) { outcome.welch_p_value = compare.welch().p_value; }
158	    return outcome;
159	}
