160	                        std::vector<std::string> const& op_labels, cmd::Workload base, std::size_t phase_index) {
161	    using PhaseStrat = strat::PhaseStrategyFor<S>;
162	    static_assert(strat::ExperimentPhaseStrategy<PhaseStrat>, "INC-E Concept-Guard: Phase-Strategy unvollstaendig");
163	    using EngineA = typename PhaseCompositions<S>::EngineA;
164	    using EngineB = typename PhaseCompositions<S>::EngineB;
165	
166	    std::string const axis_id = std::string{PhaseStrat::phase_name()}; // == merge-Name (stabile Phasen-Identitaet)
167	    std::size_t       op_idx  = 0;
168	    for (auto const& op_label : op_labels) {
169	        cmd::Workload wl = base;
170	        (void)apply_op_type_token(op_label, wl);                     // OP-Typ -> WorkloadKind (op_type_filter)
171	        wl.seed = base.seed + phase_index * 997U + (op_idx++) * 31U; // distinktes Seed je (phase,op) -> unabhaengig
172	
173	        std::string const variant = phase.name + "@" + op_label;
174	        auto const        ko      = kat::execute_one_permutation_katalog<EngineA, EngineB>(axis_id, variant, wl);
175	
176	        switch (ko.verdict) {
177	            case cmd::CompareEngineCommand::Verdict::EE_A_Wins: ++report.ee_a_wins; break;
178	            case cmd::CompareEngineCommand::Verdict::EE_B_Wins: ++report.ee_b_wins; break;
179	            case cmd::CompareEngineCommand::Verdict::Tie: ++report.ties; break;
180	            default: break;
181	        }
182	        ++report.total_variants;
183	        report.outcomes.push_back(to_permutation_outcome(ko));
184	    }
185	}
